questionvariables.text:
sides:rand(4)+5;
poly: if sides=5 then "pentagon" else if sides=6 then "hexagon" else if sides=7 then "heptagon" else "octagon";

/* Point lying on polygon edge forming angle */
anglePoint: if sides=5 then "[2.24,2.8]" else if sides=6 then "[2.5,1.6]" else if sides=7 then "[4.1,2.9]" else "[2,0]";

/* Display settings */
zoom: if sides=5 then "1.6" else if sides=6 then "1.5" else if sides=7 then "1.35" else "1.25";
box: if sides=5 then "[-5,4,5,-6]" else if sides=6 then "[-5,4.35,5,-5.65]" else if sides=7 then "[-5,5,5,-5]" else "[-5,5.3,5,-4.7]";

/* Solution */
sol:floor((360/sides)+90);

feedbackvariables.text:
/* Node 1: Check correct answer */
/* Node 2: Worked solution */
/* Node 3: Check if sum of interior angles given (2) */
node3_error: 360-sol;

/* Node 4: FOR HEPTAGON ONLY: Check if answer given as decimal or rounded incorrectly (2) */
node4_test: if sides=7 and ceiling(ans1)=142 then 1 else 0;

/* Node 5: FOR HEPTAGON ONLY: Check if sum of interior angles given as decimal or rounded incorrectly (1) */
node5_test: if sides=7 and floor(ans1)=218 then 1 else 0;
